// Define which users/endpoints this run should check.
// One clean user, one intentionally buggy user, so the pipeline
// has both a PASS case and a real anomaly to catch each run.
return [
  { json: { userId: 'user-001' } },
  { json: { userId: 'user-002' } },
  { json: { userId: 'buggy-user' } }
];

// Recompute the expected stress score independently of the API
// (RMSSD-based HRV calc) and compare against what the API returned.
// This is the actual "calculation validation" step.

const body = $input.item.json;
const rr = body.rr_intervals;

const diffs = [];
for (let i = 0; i < rr.length - 1; i++) diffs.push(rr[i + 1] - rr[i]);
const meanSquare = diffs.reduce((s, d) => s + d * d, 0) / diffs.length;
const rmssd = Math.sqrt(meanSquare);
const expected = Math.round(Math.max(0, Math.min(100, 100 - rmssd * 2)) * 10) / 10;

const actual = body.stress_score;
const delta = Math.round(Math.abs(expected - actual) * 10) / 10;
const TOLERANCE = 3.0;

let severity = 'none';
if (delta > TOLERANCE * 3) severity = 'high';
else if (delta > TOLERANCE) severity = 'medium';

return [{
  json: {
    userId: body.userId,
    checked_at: body.timestamp,
    endpoint: `/api/vitals/${body.userId}/stress`,
    rr_intervals: rr,
    expected_value: expected,
    actual_value: actual,
    delta,
    severity,
    pass: severity === 'none'
  }
}];

