// Extract the JSON the model returned and merge it with the
// original validation data so both flow downstream together.
const llmText = $input.item.json.content?.[0]?.text || '{}';
let parsed;
try {
  const cleaned = llmText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { likely_cause: 'unparseable LLM response', suggested_test: '', confidence: 'low' };
}

const upstream = $('Validate Calculation').item.json;

return [{
  json: {
    ...upstream,
    ai_explanation: parsed
  }
}];

